import React, { useState, useRef, useEffect } from 'react';
import { Camera, Scan, UserCheck } from 'lucide-react';
import { simulateQRScan } from '../../utils/realQRGenerator';

const QRScanner = ({ onScanSuccess, onScanError }) => {
  const [isScanning, setIsScanning] = useState(false);
  const [scanResult, setScanResult] = useState(null);
  const videoRef = useRef(null);

  const startScanning = async () => {
    setIsScanning(true);
    setScanResult(null);
    
    try {
      // En un sistema real, aquí inicializarías la cámara
      // Para desarrollo, simulamos el escaneo
      
      console.log('🎥 Iniciando cámara...');
      
      // Simular acceso a cámara
      const stream = await navigator.mediaDevices.getUserMedia({ 
        video: { facingMode: 'environment' } 
      });
      
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
      
      // Simular detección de QR después de 2 segundos
      setTimeout(async () => {
        const result = await simulateQRScan();
        handleScanResult(result);
      }, 2000);
      
    } catch (error) {
      console.error('❌ Error accediendo a la cámara:', error);
      // En desarrollo, simular escaneo sin cámara
      const result = await simulateQRScan();
      handleScanResult(result);
    }
  };

  const handleScanResult = (result) => {
    setScanResult(result);
    
    if (result.success) {
      console.log('✅ Empleado detectado:', result.data);
      onScanSuccess?.(result.data);
    } else {
      console.error('❌ Error en escaneo:', result.message);
      onScanError?.(result.message);
    }
    
    setIsScanning(false);
  };

  const stopScanning = () => {
    setIsScanning(false);
    if (videoRef.current && videoRef.current.srcObject) {
      const stream = videoRef.current.srcObject;
      const tracks = stream.getTracks();
      tracks.forEach(track => track.stop());
    }
  };

  return (
    <div className="bg-white rounded-2xl shadow-lg p-6">
      <div className="flex items-center mb-4">
        <Camera className="h-6 w-6 text-indigo-600 mr-2" />
        <h3 className="text-xl font-bold text-gray-900">Escáner de QR</h3>
      </div>

      <div className="space-y-4">
        {/* Área de la cámara */}
        <div className="relative bg-gray-100 rounded-lg h-64 flex items-center justify-center border-2 border-dashed border-gray-300">
          {isScanning ? (
            <>
              <video
                ref={videoRef}
                autoPlay
                playsInline
                className="w-full h-full object-cover rounded-lg"
              />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-48 h-48 border-2 border-green-500 rounded-lg animate-pulse">
                  <Scan className="h-12 w-12 text-green-500 mx-auto mt-4" />
                </div>
              </div>
            </>
          ) : (
            <div className="text-center">
              <Camera className="h-12 w-12 text-gray-400 mx-auto mb-2" />
              <p className="text-gray-600">Cámara lista para escanear</p>
            </div>
          )}
        </div>

        {/* Controles */}
        <div className="flex gap-2">
          {!isScanning ? (
            <button
              onClick={startScanning}
              className="flex-1 bg-indigo-600 text-white py-3 rounded-lg font-medium hover:bg-indigo-700 transition-colors flex items-center justify-center"
            >
              <Scan className="h-5 w-5 mr-2" />
              Iniciar Escaneo
            </button>
          ) : (
            <button
              onClick={stopScanning}
              className="flex-1 bg-red-600 text-white py-3 rounded-lg font-medium hover:bg-red-700 transition-colors"
            >
              Detener Escaneo
            </button>
          )}
        </div>

        {/* Resultado del escaneo */}
        {scanResult && (
          <div className={`p-4 rounded-lg ${
            scanResult.success 
              ? 'bg-green-50 border border-green-200' 
              : 'bg-red-50 border border-red-200'
          }`}>
            <div className="flex items-center">
              {scanResult.success ? (
                <>
                  <UserCheck className="h-5 w-5 text-green-600 mr-2" />
                  <span className="text-green-800 font-medium">
                    {scanResult.message}
                  </span>
                </>
              ) : (
                <>
                  <Camera className="h-5 w-5 text-red-600 mr-2" />
                  <span className="text-red-800 font-medium">
                    {scanResult.message}
                  </span>
                </>
              )}
            </div>
            
            {scanResult.success && scanResult.data && (
              <div className="mt-2 text-sm text-gray-700">
                <p><strong>Empleado:</strong> {scanResult.data.name}</p>
                <p><strong>ID:</strong> {scanResult.data.employeeId}</p>
                <p><strong>Departamento:</strong> {scanResult.data.department}</p>
                <p><strong>Hora:</strong> {new Date(scanResult.data.timestamp).toLocaleTimeString()}</p>
              </div>
            )}
          </div>
        )}

        {/* Instrucciones */}
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-3">
          <h4 className="font-medium text-blue-800 mb-1">Instrucciones:</h4>
          <ul className="text-sm text-blue-700 list-disc list-inside space-y-1">
            <li>Coloque el código QR frente a la cámara</li>
            <li>Asegúrese de que haya buena iluminación</li>
            <li>Mantenga estable el dispositivo</li>
            <li>El sistema registrará automáticamente la asistencia</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default QRScanner;
